// validate-bcpss-activity-lessons — every Language Studio activity is tied to specific lesson(s) of its own unit.
//
// Reads db/seeds/bcpss/v2/lesson-links/<unit>.mjs (generated by tools/build-bcpss-activity-lessons.mjs) against the
// live studio and lesson data and fails when:
//   - the generated files are stale (the generator's --check),
//   - a unit has no link file, or its activity list differs from the studio's (count, kind or title),
//   - an activity has no lesson, or names a lesson that is not in its unit (id, sequence or title differ),
//   - the reverse index disagrees with the forward one,
//   - a link claims a reason ("uses", "terms", "topic") the data does not support,
//   - a Reveal Math link points at a lesson folder this repo does not have, or appears outside Grade 6 math.
//   - more than 2% of lessons have no activity at all (a few are allowed: no link without a real signal).
// A sweep that covered fewer activities than data/sweep-floors.json pins also fails.
import { execFileSync } from "node:child_process";
import path from "node:path";
import process from "node:process";
import { fileURLToPath } from "node:url";
import * as seed from "../data/bcpss-curriculum-seed.mjs";
import { loadLessonLinks } from "../functions/_lib/bcpss/lesson-links.js";
import { loadLessons } from "../functions/_lib/bcpss/lessons.js";
import { loadStudio } from "../functions/_lib/bcpss/studio.js";
import { tryLoadLessonConfig } from "./lib/curriculum-source.mjs";
import { assertSweptEnough } from "./lib/sweep-guard.mjs";

const repo = path.join(path.dirname(fileURLToPath(import.meta.url)), "..");
const HOW = new Set(["uses", "terms", "topic"]);
const problems = [];
const bad = (unit, msg) => problems.push(`${unit}: ${msg}`);

try {
  execFileSync(
    process.execPath,
    [path.join(repo, "tools/build-bcpss-activity-lessons.mjs"), "--check"],
    {
      stdio: "pipe",
    },
  );
} catch (err) {
  bad(
    "generated files",
    String(err.stderr || err.message)
      .trim()
      .split("\n")[0],
  );
}

let activities = 0;
let linked = 0;
let reveal = 0;
let idle = 0; // lessons with no activity are allowed (a link needs a real signal), but capped below
let lessonCount = 0;
for (const unit of seed.BCPSS_UNITS) {
  const [studio, set, links] = await Promise.all([
    loadStudio(unit.id),
    loadLessons(unit.id),
    loadLessonLinks(unit.id),
  ]);
  if (!links) {
    bad(unit.id, "no lesson-links file");
    continue;
  }
  const byId = new Map(set.lessons.map((l) => [l.id, l]));
  lessonCount += set.lessons.length;
  if (links.activities.length !== studio.activities.length)
    bad(
      unit.id,
      `${links.activities.length} linked activities for ${studio.activities.length} in the studio`,
    );
  studio.activities.forEach((a, i) => {
    activities++;
    const row = links.activities[i];
    if (!row || row.kind !== a.kind || row.title !== a.title || row.n !== i + 1)
      return bad(unit.id, `activity ${i + 1} "${a.title}" does not match its link row`);
    if (!row.lessons.length)
      return bad(unit.id, `activity ${i + 1} "${a.title}" is not linked to any lesson`);
    linked++;
    for (const l of row.lessons) {
      const lesson = byId.get(l.id);
      if (!lesson)
        bad(unit.id, `activity ${i + 1} links to ${l.id}, which is not a lesson of this unit`);
      else if (lesson.title !== l.title || lesson.sequence !== l.sequence)
        bad(unit.id, `activity ${i + 1} link to ${l.id} carries a stale title or sequence`);
      if (!HOW.has(l.how))
        bad(unit.id, `activity ${i + 1} link to ${l.id} has unknown reason "${l.how}"`);
      if (l.how === "terms" && !(l.terms || []).length)
        bad(unit.id, `activity ${i + 1} link to ${l.id} says "terms" but names none`);
    }
  });
  if (links.lessons.length !== set.lessons.length)
    bad(unit.id, `${links.lessons.length} lesson rows for ${set.lessons.length} lessons`);
  for (const row of links.lessons) {
    if (!byId.has(row.id)) {
      bad(unit.id, `lesson row ${row.id} is not a lesson of this unit`);
      continue;
    }
    if (!row.activities.length) idle++;
    for (const a of row.activities) {
      const fwd = links.activities[a.n - 1]?.lessons.find((l) => l.id === row.id);
      if (!fwd || fwd.how !== a.how)
        bad(unit.id, `lesson ${row.id} lists activity ${a.n} but the forward link disagrees`);
    }
    for (const r of row.reveal || []) {
      reveal++;
      if (!(unit.grade === "6" && unit.subject === "Math"))
        bad(unit.id, `lesson ${row.id} carries a Reveal Math link outside Grade 6 math`);
      if (!tryLoadLessonConfig(r.id))
        bad(unit.id, `lesson ${row.id} links Reveal Math ${r.id}, which this repo does not have`);
      if (!(r.terms || []).length)
        bad(unit.id, `lesson ${row.id} links Reveal Math ${r.id} with no shared words`);
    }
  }
}

if (idle > 0.02 * lessonCount)
  bad("coverage", `${idle} of ${lessonCount} lessons have no Studio activity (more than 2%)`);

assertSweptEnough(
  "validate:bcpss-activity-lessons",
  activities,
  "activities come from loadStudio for every unit in the seed",
);

if (problems.length) {
  console.error(`FAIL validate:bcpss-activity-lessons — ${problems.length} problem(s):`);
  for (const p of problems.slice(0, 30)) console.error(`  ${p}`);
  if (problems.length > 30) console.error(`  … and ${problems.length - 30} more`);
  process.exit(1);
}
console.log(
  `PASS validate:bcpss-activity-lessons — ${linked}/${activities} activities linked across ${seed.BCPSS_UNITS.length} units, ${reveal} Reveal Math links`,
);
